"""Market Hub list: Top 100 … 500 from the same tab (menu), remembered; coins 101–500 from GitHub's file with their
time; 100 rows at a time (more as you scroll); search covers all; Binance tops up prices it trades."""
import sys, pathlib, json
from playwright.sync_api import sync_playwright
sys.path.insert(0, str(pathlib.Path(__file__).parent)); import e2e_setup as S
SH = pathlib.Path(__file__).parent / 'shots'; res = []
FIX = (pathlib.Path(__file__).parent / 'top500_fixture.json').read_text(); T = json.loads(FIX)
SNAP = (pathlib.Path(__file__).parent / 'market_snap_fixture.json').read_text()
def check(n, c, d=''): res.append(bool(c)); print(('PASS ' if c else 'FAIL ') + n + ('' if c else f' -> {d}'), flush=True)
BN = json.dumps([{'symbol': 'ZC250USDT', 'price': str(T['top'][149]['price'] * 1.1)}, {'symbol': 'ZC499USDT', 'price': str(T['top'][398]['price'] * 9)}])   # one close (used), one far off (left alone)
ROWS = "document.querySelectorAll('#mkRows .mk-row, #mkRows [data-id]').length"
with sync_playwright() as p:
    br = p.chromium.launch()
    for vn, vp in (('phone', dict(viewport={'width': 390, 'height': 844}, is_mobile=True, has_touch=True, device_scale_factor=2)), ('desktop', dict(viewport={'width': 1366, 'height': 900}, device_scale_factor=2))):
        for theme in ('light', 'dark'):
            ctx = br.new_context(**vp); S.setup(ctx)
            ctx.route('**/prices/m/market.json', lambda r: r.fulfill(status=200, content_type='application/json', body=SNAP))
            ctx.route('https://api.coingecko.com/api/v3/coins/markets**', lambda r: r.fulfill(status=429, body='busy'))   # CoinGecko busy → the saved 150 (+ Binance)
            ctx.route('**/prices/m/top500.json', lambda r: r.fulfill(status=200, content_type='application/json', body=FIX))
            ctx.route('https://data-api.binance.vision/**', lambda r: r.fulfill(status=200, content_type='application/json', headers={'access-control-allow-origin': '*'}, body=BN))
            ctx.add_init_script(f"try{{localStorage.setItem('samsam_theme','{theme}');if(!sessionStorage.getItem('t5')){{localStorage.removeItem('samsam_mkt_topn');sessionStorage.setItem('t5','1')}}}}catch(e){{}}")
            pg = ctx.new_page(); errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
            pg.goto(S.SITE + '/index.html'); pg.click('#samsamSignInBtn'); S.wait_ready(pg); pg.goto(S.SITE + '/market.html'); pg.wait_for_function("document.querySelectorAll('#mkRows [data-id]').length > 5"); pg.wait_for_timeout(500)
            pg.evaluate(f"document.documentElement.setAttribute('data-theme','{theme}')")
            n0 = pg.evaluate("document.querySelectorAll('#mkRows [data-id]').length")
            check(f'{vn}/{theme}: starts on Top 100 ({n0} rows), no note', pg.inner_text('#topLbl') == 'Top 100' and n0 <= 100 and pg.evaluate("mkBig.hidden"), n0)
            pg.click('#tabTop'); pg.wait_for_timeout(200)
            m = pg.evaluate("({open: !topMenu.hidden, items: [...topMenu.querySelectorAll('button')].map(b=>b.textContent+(b.getAttribute('aria-checked')==='true'?'*':''))})")
            check(f'{vn}/{theme}: tapping Top 100 opens 100 · 200 · 300 · 400 · 500 {m}', m['open'] and m['items'] == ['Top 100*', 'Top 200', 'Top 300', 'Top 400', 'Top 500'], m)
            pg.screenshot(path=str(SH / f't5_menu_{vn}_{theme}.png'), clip={'x': 0, 'y': max(0, pg.locator('#tabTop').bounding_box()['y'] - 10), 'width': vp['viewport']['width'], 'height': 330})
            pg.click('#topMenu button[data-n="300"]'); pg.wait_for_function("document.querySelectorAll('#mkRows [data-id]').length >= 100 && !mkBig.hidden && /prices from/.test(mkBig.innerText)"); pg.wait_for_timeout(300)
            st = pg.evaluate("({lbl: topLbl.textContent, n: document.querySelectorAll('#mkRows [data-id]').length, more: !!document.getElementById('mkMoreRows'), note: mkBig.innerText})")
            check(f'{vn}/{theme}: Top 300 — first 100 rows, more to come, note with the time {st}', st['lbl'] == 'Top 300' and st['n'] == 100 and st['more'] and 'Coins 101–300' in st['note'], st)
            for _ in range(4):
                pg.evaluate("document.getElementById('mkMoreRows')?.scrollIntoView()"); pg.wait_for_timeout(500)
            n = pg.evaluate("document.querySelectorAll('#mkRows [data-id]').length")
            check(f'{vn}/{theme}: scrolling down loads the rest (300 rows)', n == 300 and not pg.evaluate("!!document.getElementById('mkMoreRows')"), n)
            check(f'{vn}/{theme}: Binance tops up a coin it trades (close price) and leaves a far-off one alone', 'Binance' in pg.inner_text('#mkBig') and pg.evaluate("bigRows.find(r=>r.sym==='ZC250').bn > 0 && !bigRows.find(r=>r.sym==='ZC499').bn"))
            # the + button and the links work for a coin past 100 (ranked 287 here)
            pg.fill('#mkSearch', 'Zed Coin 287'); pg.wait_for_timeout(300)
            pg.click('#mkRows [data-id="zcoin-287"] .mk-add'); pg.wait_for_timeout(300)
            menu = pg.evaluate("[...document.querySelectorAll('.cp-menu button, .cp-menu a, [role=menu] [role=menuitem]')].filter(e=>e.offsetParent).map(e=>e.innerText.trim())")
            check(f'{vn}/{theme}: + on a coin ranked 287 opens Add to Portfolio / Plan / Watchlist {menu}', any('Add to Portfolio' in m for m in menu) and any('Watchlist' in m for m in menu), menu)
            pg.keyboard.press('Escape'); pg.wait_for_timeout(200)
            pg.evaluate("toggleLinks('zcoin-287')"); pg.wait_for_timeout(300)
            ln = pg.evaluate("(()=>{const b=document.getElementById('mkl-zcoin-287'); return {pred: b.querySelector('.l-pred').outerHTML, cmc: b.querySelector('.l-cmc').innerText, href: b.querySelector('.l-cmc').href}})()")
            check(f'{vn}/{theme}: a coin CoinMarketCap / CoinCodex don\'t list: the button says CoinGecko, Prediction is a plain note (no web search) {ln}', 'No prediction' in ln['pred'] and 'href' not in ln['pred'] and ('CoinGecko' in ln['cmc']) == ('coingecko.com' in ln['href']) and 'google' not in ln['href'], ln)
            pg.evaluate("toggleLinks('zcoin-287')")
            check(f'{vn}/{theme}: search finds a coin ranked 287', pg.evaluate("[...document.querySelectorAll('#mkRows [data-id]')].map(r=>r.dataset.id)") == ['zcoin-287'])
            pg.fill('#mkSearch', ''); pg.wait_for_timeout(200)
            pg.click('.mk-chip[data-f=gain]'); pg.wait_for_timeout(300)
            g = pg.evaluate("rowsNow().length")
            check(f'{vn}/{theme}: Gainers works on all 300 ({g})', 0 < g < 300, g)
            pg.click('.mk-chip[data-f=all]')
            pg.reload(); pg.wait_for_function("document.querySelectorAll('#mkRows [data-id]').length > 5"); pg.wait_for_timeout(1500)
            check(f'{vn}/{theme}: Top 300 remembered next time', pg.inner_text('#topLbl') == 'Top 300' and not pg.evaluate("mkBig.hidden"))
            pg.click('#tabWatch'); pg.wait_for_timeout(300)
            check(f'{vn}/{theme}: other tabs hide the note', pg.evaluate("mkBig.hidden"))
            pg.click('#tabTop'); pg.wait_for_timeout(200)
            check(f'{vn}/{theme}: from another tab, Top 300 opens straight away (no menu)', pg.evaluate("topMenu.hidden") and pg.evaluate("document.getElementById('tabTop').getAttribute('aria-selected')") == 'true')
            pg.click('#tabTop'); pg.wait_for_timeout(200); pg.keyboard.press('Escape'); pg.wait_for_timeout(100)
            check(f'{vn}/{theme}: Esc closes the menu', pg.evaluate("topMenu.hidden"))
            check(f'{vn}/{theme}: no sideways scrolling', pg.evaluate("document.documentElement.scrollWidth <= innerWidth + 1"))
            check(f'{vn}/{theme}: no JS errors', not errs, errs[:3]); ctx.close()
    br.close()
print(f'{sum(res)}/{len(res)} passed'); sys.exit(0 if all(res) else 1)
